            new SshSnippet { Name = "Состояния сводка", Group = "Процессы", Command = "ps -e -o stat= | sort | uniq -c | sort -rn", Description = "Сводка состояний R/S/D/Z со счётчиками" },
            new SshSnippet { Name = "D-сон", Group = "Процессы", Command = "ps -e -o pid,stat,wchan:20,cmd | awk '$2 ~ /D/ {print}' | head -10", Description = "Непрерываемый сон: обычно проблемы с диском" },
            new SshSnippet { Name = "RSS топ-10", Group = "Процессы", Command = "ps -e -o pid,rss,comm --sort=-rss | head -11", Description = "Резидентная память в килобайтах" },
            new SshSnippet { Name = "VSZ топ-10", Group = "Процессы", Command = "ps -e -o pid,vsz,comm --sort=-vsz | head -11", Description = "Виртуальная память процессов" },
            new SshSnippet { Name = "Держатели файлов", Group = "Процессы", Command = "lsof 2>/dev/null | awk '{print $1}' | sort | uniq -c | sort -rn | head -10", Description = "Какие программы держат больше всего файлов" },
            new SshSnippet { Name = "Кто на терминалах", Group = "Процессы", Command = "ps -e -o pid,tty,cmd | grep -E \"pts/|tty\" | head -15", Description = "Процессы с привязкой к терминалам" },
            new SshSnippet { Name = "Лимиты init", Group = "Процессы", Command = "cat /proc/1/limits 2>/dev/null | head -20", Description = "Лимиты ресурсов PID 1" },
            new SshSnippet { Name = "Окружение init", Group = "Процессы", Command = "tr '\\0' '\\n' < /proc/1/environ 2>/dev/null | head -20", Description = "Переменные окружения init-процесса" },
            new SshSnippet { Name = "Дескрипторов всего", Group = "Процессы", Command = "ls /proc/[0-9]*/fd 2>/dev/null | wc -l", Description = "Число открытых файловых дескрипторов" },
            new SshSnippet { Name = "Процессов счёт", Group = "Процессы", Command = "ps -e | wc -l", Description = "Общее число процессов" },
            new SshSnippet { Name = "Потоков счёт", Group = "Процессы", Command = "ps -eLF | wc -l", Description = "Общее число потоков" },
            new SshSnippet { Name = "Процессы по юзерам", Group = "Процессы", Command = "ps -e -o user= | sort | uniq -c | sort -rn", Description = "Сколько процессов у каждого пользователя" },
            new SshSnippet { Name = "От root", Group = "Процессы", Command = "ps -U root -u root -o pid,cmd | head -20", Description = "Что крутится от имени root" },
            new SshSnippet { Name = "Демоны", Group = "Процессы", Command = "ps -e -o pid,tty,cmd | awk '$2 == \"?\" {print}' | head -15", Description = "Фоновые процессы без терминала" },
            new SshSnippet { Name = "Простой IO", Group = "Процессы", Command = "vmstat 1 2 | tail -1 | awk '{print \"iowait=\" $16\"%\"}'", Description = "Процент ожидания дискового IO" },
            new SshSnippet { Name = "Переключения", Group = "Процессы", Command = "vmstat 1 2 | tail -1 | awk '{print \"cs=\" $12}'", Description = "Контекстные переключения в секунду" },
            new SshSnippet { Name = "Прерывания", Group = "Процессы", Command = "vmstat 1 2 | tail -1 | awk '{print \"in=\" $11}'", Description = "Аппаратные прерывания в секунду" },
            new SshSnippet { Name = "Всего форков", Group = "Процессы", Command = "cat /proc/stat | grep processes", Description = "Сколько процессов создано с загрузки" },
            new SshSnippet { Name = "Очередь CPU", Group = "Процессы", Command = "cat /proc/loadavg | awk '{print \"runq: \" $4}'", Description = "Длина очереди планировщика" },
            new SshSnippet { Name = "Свои IP", Group = "Сеть", Command = "hostname -I", Description = "Все собственные IP-адреса хоста одной строкой" },
            new SshSnippet { Name = "IPv6 глобальные", Group = "Сеть", Command = "ip -6 addr show scope global 2>/dev/null | head -10", Description = "Глобальные IPv6-адреса интерфейсов" },
            new SshSnippet { Name = "MTU", Group = "Сеть", Command = "ip link show | grep -E \"mtu|^[0-9]\" | head -20", Description = "MTU каждого сетевого интерфейса" },
            new SshSnippet { Name = "Промиск-режим", Group = "Сеть", Command = "ip link show | grep -i promisc | head -3", Description = "Включён ли на интерфейсах режим сниффера" },
            new SshSnippet { Name = "Потери пакетов", Group = "Сеть", Command = "ping -c 10 -q 8.8.8.8 | tail -3", Description = "Процент потерь и джиттер за 10 пакетов" },
            new SshSnippet { Name = "Скорость резолва", Group = "Сеть", Command = "time getent hosts ya.ru", Description = "Сколько времени занимает DNS-ответ" },
            new SshSnippet { Name = "Порядок резолва", Group = "Сеть", Command = "grep -v \"^#\" /etc/nsswitch.conf 2>/dev/null | grep hosts", Description = "Что раньше: files или DNS" },
            new SshSnippet { Name = "Статика ARP", Group = "Сеть", Command = "ip neigh show | grep PERMANENT | head -10", Description = "Статические ARP-записи таблицы соседей" },
            new SshSnippet { Name = "UDP-сокеты", Group = "Сеть", Command = "ss -ulnp 2>/dev/null | head -15", Description = "Слушающие UDP-порты с процессами" },
            new SshSnippet { Name = "TCP-сокеты", Group = "Сеть", Command = "ss -tlnp 2>/dev/null | head -20", Description = "Слушающие TCP-порты с процессами" },
            new SshSnippet { Name = "Живых соединений", Group = "Сеть", Command = "ss -tun state established 2>/dev/null | wc -l", Description = "Число соединений в статусе ESTABLISHED" },
            new SshSnippet { Name = "TIME_WAIT", Group = "Сеть", Command = "ss -tun state time-wait 2>/dev/null | wc -l", Description = "Залипшие закрывающиеся соединения" },
            new SshSnippet { Name = "Топ связей", Group = "Сеть", Command = "ss -tun 2>/dev/null | awk 'NR>1 {print $5}' | cut -d: -f1 | sort | uniq -c | sort -rn | head -10", Description = "С какими адресами больше всего связей" },
            new SshSnippet { Name = "Сводка сокетов", Group = "Сеть", Command = "ss -s 2>/dev/null | head -12", Description = "Сводка подсистемы сокетов по типам" },
            new SshSnippet { Name = "Счётчики стека", Group = "Сеть", Command = "nstat 2>/dev/null | head -30", Description = "Счётчики TCP/IP стека ядра" },
            new SshSnippet { Name = "Фаервол", Group = "Сеть", Command = "(command -v ufw >/dev/null && sudo -n ufw status 2>&1 | head -5); (command -v firewall-cmd >/dev/null && firewall-cmd --state 2>&1); true", Description = "Статус ufw или firewalld, что есть" },
            new SshSnippet { Name = "NAT-правила", Group = "Сеть", Command = "iptables -t nat -S 2>/dev/null | head -20 || echo \"нет доступа\"", Description = "Таблица NAT трансляции адресов" },
            new SshSnippet { Name = "Фильтр-правила", Group = "Сеть", Command = "iptables -S 2>/dev/null | head -20 || echo \"нет доступа\"", Description = "Правила фильтрации пакетов" },
            new SshSnippet { Name = "Слушает 443?", Group = "Сеть", Command = "ss -tlnp 2>/dev/null | grep :443 || echo \"443 закрыт\"", Description = "Кто слушает HTTPS-порт (пример)" },
            new SshSnippet { Name = "Пинг шлюза", Group = "Сеть", Command = "gw=$(ip route show default 2>/dev/null | awk '{print $3}'); ping -c 4 -q $gw | tail -2", Description = "Отклик шлюза по умолчанию" },
            new SshSnippet { Name = "Скорость линка", Group = "Сеть", Command = "ethtool $(ip route show default 2>/dev/null | awk '{print $5}') 2>/dev/null | grep -iE \"speed|duplex|link\" | head -5 || echo \"нет ethtool\"", Description = "Скорость и дуплекс основного интерфейса" },
            new SshSnippet { Name = "Мосты", Group = "Сеть", Command = "ip link show type bridge 2>/dev/null | head -10 || echo \"бриджей нет\"", Description = "Сетевые мосты хоста" },
            new SshSnippet { Name = "VLANы", Group = "Сеть", Command = "ip link show | grep -E \"@|\\.[0-9]+@\" | head -10 || echo \"vlan нет\"", Description = "VLAN-интерфейсы и их родители" },
            new SshSnippet { Name = "WireGuard", Group = "Сеть", Command = "(command -v wg >/dev/null && sudo -n wg show 2>&1 | head -20) || echo \"wg нет\"", Description = "Туннели WireGuard и пиры" },
            new SshSnippet { Name = "Маршруты IPv6", Group = "Сеть", Command = "ip -6 route show 2>/dev/null | head -10", Description = "Таблица маршрутизации IPv6" },
            new SshSnippet { Name = "Свой DNS?", Group = "Сеть", Command = "ss -ulnp 2>/dev/null | grep :53 || echo \"53 не слушается\"", Description = "Крутится ли свой DNS-сервер" },
            new SshSnippet { Name = "Свой NTP?", Group = "Сеть", Command = "ss -ulnp 2>/dev/null | grep :123 || echo \"ntp не слушается\"", Description = "Крутится ли свой NTP-сервер" },
            new SshSnippet { Name = "Файловые системы", Group = "Диски", Command = "df -h", Description = "Занятость всех смонтированных разделов" },
            new SshSnippet { Name = "Иноды разделов", Group = "Диски", Command = "df -i", Description = "Свободные иноды по файловым системам" },
            new SshSnippet { Name = "Разделы и точки", Group = "Диски", Command = "lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT", Description = "Диски с типами ФС и точками монтирования" },
            new SshSnippet { Name = "UUID разделов", Group = "Диски", Command = "blkid 2>/dev/null | head -15 || ls -l /dev/disk/by-uuid/", Description = "Идентификаторы разделов для fstab" },
            new SshSnippet { Name = "Что смонтировано", Group = "Диски", Command = "mount | grep -E \"^/dev\"", Description = "Дисковые монтирования из mount" },
            new SshSnippet { Name = "Автомонтирование", Group = "Диски", Command = "grep -v \"^#\" /etc/fstab | grep -v \"^$\"", Description = "Содержимое fstab без комментариев" },
            new SshSnippet { Name = "LVM PV", Group = "Диски", Command = "pvs 2>/dev/null || echo \"lvm нет\"", Description = "Физические тома LVM" },
            new SshSnippet { Name = "LVM VG", Group = "Диски", Command = "vgs 2>/dev/null || echo \"lvm нет\"", Description = "Группы томов LVM" },
            new SshSnippet { Name = "LVM LV", Group = "Диски", Command = "lvs 2>/dev/null || echo \"lvm нет\"", Description = "Логические тома LVM" },
            new SshSnippet { Name = "Софт-рейды", Group = "Диски", Command = "cat /proc/mdstat", Description = "Состояние программных RAID mdadm" },
            new SshSnippet { Name = "Жирное в корне", Group = "Диски", Command = "du -sh /* 2>/dev/null | sort -h | tail -12", Description = "Двенадцать самых тяжёлых каталогов корня" },
            new SshSnippet { Name = "Жирное в /var", Group = "Диски", Command = "du -sh /var/* 2>/dev/null | sort -h | tail -10", Description = "Десятка тяжёлого в /var" },
            new SshSnippet { Name = "Жирное в /home", Group = "Диски", Command = "du -sh /home/* 2>/dev/null | sort -h | tail -10 || echo \"home пуст\"", Description = "Тяжёлые домашние каталоги" },
            new SshSnippet { Name = "Мусор в /tmp", Group = "Диски", Command = "du -sh /tmp/* 2>/dev/null | sort -h | tail -10", Description = "Что отъедает /tmp" },
            new SshSnippet { Name = "Удалённые занятые", Group = "Диски", Command = "lsof 2>/dev/null | grep -i deleted | head -10 || echo \"таких нет\"", Description = "Удалённые файлы, держащие место на диске" },
            new SshSnippet { Name = "Файлы больше гига", Group = "Диски", Command = "find / -maxdepth 4 -type f -size +1G 2>/dev/null | head -10", Description = "Файлы больше 1 ГБ на верхних уровнях" },
            new SshSnippet { Name = "Файлы больше 100М", Group = "Диски", Command = "find / -maxdepth 5 -type f -size +100M 2>/dev/null | head -15", Description = "Файлы больше 100 МБ" },
            new SshSnippet { Name = "Тип ФС корня", Group = "Диски", Command = "findmnt -n -o FSTYPE /", Description = "ext4, xfs или btrfs на корне" },
            new SshSnippet { Name = "Опции корня", Group = "Диски", Command = "findmnt -n -o OPTIONS / | tr ',' '\\n'", Description = "Опции монтирования корня построчно" },
            new SshSnippet { Name = "Нагрузка дисков", Group = "Диски", Command = "iostat 1 2 2>/dev/null | tail -8 || vmstat 1 2 | tail -1", Description = "Нагрузка дисков, фолбэк на vmstat" },
            new SshSnippet { Name = "Планировщики IO", Group = "Диски", Command = "cat /sys/block/*/queue/scheduler 2>/dev/null | head -10", Description = "IO-планировщики дисков, активный в скобках" },
            new SshSnippet { Name = "Блочные устройства", Group = "Диски", Command = "ls /sys/block/ | tr '\\n' ' '", Description = "Список блочных устройств ядра" },
            new SshSnippet { Name = "Только чтение", Group = "Диски", Command = "findmnt -n -o TARGET,OPTIONS | grep -i \"ro,\" | head -10 || echo \"все rw\"", Description = "Точки, примонтированные read-only" },
            new SshSnippet { Name = "Место boot", Group = "Диски", Command = "df -h /boot | tail -1", Description = "Не забит ли раздел /boot" },
            new SshSnippet { Name = "Квоты", Group = "Диски", Command = "quota -s 2>/dev/null || echo \"квот нет\"", Description = "Дисковые квоты пользователя" },
            new SshSnippet { Name = "Точный старт", Group = "Система", Command = "uptime -s 2>/dev/null || uptime", Description = "Точная дата загрузки, фолбэк на обычный uptime" },
            new SshSnippet { Name = "VM или железо", Group = "Система", Command = "systemd-detect-virt 2>/dev/null || echo \"похоже, физика\"", Description = "Виртуалка (kvm/vmware) или физический сервер" },
            new SshSnippet { Name = "В контейнере?", Group = "Система", Command = "systemd-detect-virt --container 2>/dev/null || echo \"не контейнер\"", Description = "Запущены ли внутри docker/lxc" },
            new SshSnippet { Name = "Архитектура CPU", Group = "Система", Command = "arch || uname -m", Description = "x86_64, aarch64 или другая" },
            new SshSnippet { Name = "Модель CPU", Group = "Система", Command = "grep \"model name\" /proc/cpuinfo | head -1 | cut -d: -f2", Description = "Маркетинговое название процессора" },
            new SshSnippet { Name = "Ядер числом", Group = "Система", Command = "nproc; grep -c ^processor /proc/cpuinfo", Description = "Число ядер двумя независимыми способами" },
            new SshSnippet { Name = "Параметры ядра", Group = "Система", Command = "cat /proc/cmdline", Description = "С какими опциями загрузилось ядро" },
            new SshSnippet { Name = "Релиз ядра", Group = "Система", Command = "uname -r", Description = "Короткая версия ядра" },
            new SshSnippet { Name = "Дистрибутив коротко", Group = "Система", Command = "lsb_release -ds 2>/dev/null || grep PRETTY_NAME /etc/os-release | cut -d= -f2", Description = "Название дистрибутива одной строкой" },
            new SshSnippet { Name = "Таргет загрузки", Group = "Система", Command = "systemctl get-default 2>/dev/null || runlevel 2>/dev/null", Description = "Куда грузится: multi-user или graphical" },
            new SshSnippet { Name = "Время загрузки", Group = "Система", Command = "systemd-analyze 2>&1 | head -5", Description = "Сколько секунд грузились ядро и userspace" },
            new SshSnippet { Name = "Тормоза старта", Group = "Система", Command = "systemd-analyze blame 2>&1 | head -10", Description = "Десять самых долгих юнитов старта" },
            new SshSnippet { Name = "Таймзона", Group = "Система", Command = "timedatectl 2>/dev/null | grep -i zone || date +%Z", Description = "Название часового пояса" },
            new SshSnippet { Name = "Язык системы", Group = "Система", Command = "localectl 2>/dev/null | head -8 || locale | head -8", Description = "Локаль, язык и раскладка" },
            new SshSnippet { Name = "История ребутов", Group = "Система", Command = "last reboot | head -10", Description = "Когда сервер перезагружали" },
            new SshSnippet { Name = "История выключений", Group = "Система", Command = "last -x shutdown | head -10", Description = "Когда сервер гасили" },
            new SshSnippet { Name = "Аптайм днями", Group = "Система", Command = "cat /proc/uptime | awk '{print int($1/86400)\" дн\"}'", Description = "Время работы целыми днями" },
            new SshSnippet { Name = "Инит-процесс", Group = "Система", Command = "ps -p 1 -o comm=", Description = "systemd или классический sysvinit" },
            new SshSnippet { Name = "Упавшие юниты", Group = "Службы", Command = "systemctl --no-pager --type=service --state=failed", Description = "Сервисы в состоянии failed — первые кандидаты на разбор" },
            new SshSnippet { Name = "Все сервисы", Group = "Службы", Command = "systemctl list-units --no-pager --all --type=service | head -30", Description = "Все юниты сервисов скопом с состояниями" },
            new SshSnippet { Name = "Автозапуск вкл", Group = "Службы", Command = "systemctl list-unit-files --type=service --state=enabled --no-pager | head -20", Description = "Что стартует само при загрузке" },
            new SshSnippet { Name = "Автозапуск выкл", Group = "Службы", Command = "systemctl list-unit-files --type=service --state=disabled --no-pager | head -20", Description = "Сервисы, отключённые от автозапуска" },
            new SshSnippet { Name = "Замаскированные", Group = "Службы", Command = "systemctl list-unit-files --type=service --state=masked --no-pager | head -10", Description = "Юниты, заблокированные через mask" },
            new SshSnippet { Name = "Таймеры systemd", Group = "Службы", Command = "systemctl list-timers --no-pager | head -15", Description = "Таймеры планировщика с расписанием" },
            new SshSnippet { Name = "Сокеты", Group = "Службы", Command = "systemctl list-sockets --no-pager | head -15", Description = "Сокеты socket-активации сервисов" },
            new SshSnippet { Name = "Таргеты", Group = "Службы", Command = "systemctl list-units --type=target --no-pager | head -10", Description = "Цели загрузки systemd" },
            new SshSnippet { Name = "SSH жив?", Group = "Службы", Command = "systemctl is-active ssh sshd 2>/dev/null; systemctl is-enabled ssh sshd 2>/dev/null", Description = "Активен ли sshd и включён ли в автозапуск" },
            new SshSnippet { Name = "Cron жив?", Group = "Службы", Command = "systemctl is-active cron crond 2>/dev/null; systemctl is-enabled cron crond 2>/dev/null", Description = "Работает ли планировщик cron" },
            new SshSnippet { Name = "Docker жив?", Group = "Службы", Command = "systemctl is-active docker 2>/dev/null || echo \"docker нет\"", Description = "Запущен ли демон Docker" },
            new SshSnippet { Name = "Зависимости SSH", Group = "Службы", Command = "systemctl list-dependencies ssh --no-pager 2>/dev/null || systemctl list-dependencies sshd --no-pager 2>/dev/null | head -15", Description = "От каких юнитов зависит SSH" },
            new SshSnippet { Name = "Юнит-файл SSH", Group = "Службы", Command = "systemctl cat ssh 2>/dev/null || systemctl cat sshd 2>/dev/null | head -30", Description = "Содержимое юнит-файла SSH-сервера" },
            new SshSnippet { Name = "Логи cron", Group = "Службы", Command = "journalctl -u cron --no-pager -n 15 2>/dev/null || journalctl -u crond --no-pager -n 15 2>/dev/null", Description = "Свежие записи журнала планировщика" },
            new SshSnippet { Name = "Логи docker", Group = "Службы", Command = "journalctl -u docker --no-pager -n 15 2>/dev/null", Description = "Свежие записи журнала Docker" },
            new SshSnippet { Name = "Рестарты sshd", Group = "Службы", Command = "systemctl show -p NRestarts sshd 2>/dev/null || echo \"-\"", Description = "Сколько раз перезапускался sshd" },
            new SshSnippet { Name = "Память sshd", Group = "Службы", Command = "systemctl show sshd -p MemoryCurrent 2>/dev/null || echo \"-\"", Description = "Потребление памяти юнитом sshd" },
            new SshSnippet { Name = "PID sshd", Group = "Службы", Command = "systemctl show sshd -p MainPID --value 2>/dev/null || systemctl show ssh -p MainPID --value 2>/dev/null", Description = "Главный PID SSH-сервера" },
            new SshSnippet { Name = "Init-скрипты", Group = "Службы", Command = "service --status-all 2>&1 | head -20", Description = "Старые SysV-скрипты и их статусы" },
            new SshSnippet { Name = "Описание sshd", Group = "Службы", Command = "systemctl show sshd -p Description --value 2>/dev/null || echo \"-\"", Description = "Человеческое описание юнита" },
            new SshSnippet { Name = "Путь юнита", Group = "Службы", Command = "systemctl show sshd -p FragmentPath --value 2>/dev/null || echo \"-\"", Description = "Где лежит юнит-файл sshd" },
            new SshSnippet { Name = "Ошибки с загрузки", Group = "Службы", Command = "journalctl --no-pager -p err -b -n 15", Description = "Ошибки сервисов с текущей загрузки" },
            new SshSnippet { Name = "Сокет SSH", Group = "Службы", Command = "systemctl status ssh.socket --no-pager 2>/dev/null | head -8 || echo \"сокета нет\"", Description = "SSH через socket-активацию" },
            new SshSnippet { Name = "Активное всё", Group = "Службы", Command = "systemctl list-units --state=active --no-pager | head -20", Description = "Всё активное разом: сервисы, сокеты, таргеты" },
            new SshSnippet { Name = "Старт sshd когда", Group = "Службы", Command = "systemctl show sshd -p ActiveEnterTimestamp --value 2>/dev/null || echo \"-\"", Description = "Когда sshd перешёл в active" },
            new SshSnippet { Name = "Ошибки загрузки", Group = "Журналы", Command = "journalctl -p err -b --no-pager -n 20", Description = "Ошибки ядра и сервисов текущей загрузки" },
            new SshSnippet { Name = "Варнинги загрузки", Group = "Журналы", Command = "journalctl -p warning -b --no-pager -n 20", Description = "Предупреждения с текущей загрузки" },
            new SshSnippet { Name = "Ошибки со вчера", Group = "Журналы", Command = "journalctl --no-pager -p err --since yesterday -n 20", Description = "Ошибки журнала за последние сутки" },
            new SshSnippet { Name = "Всё за час", Group = "Журналы", Command = "journalctl --no-pager --since \"1 hour ago\" -n 30", Description = "Все события последнего часа" },
            new SshSnippet { Name = "Ядро из журнала", Group = "Журналы", Command = "journalctl -k --no-pager -n 20", Description = "Сообщения ядра через journald" },
            new SshSnippet { Name = "Вес журнала", Group = "Журналы", Command = "journalctl --disk-usage", Description = "Сколько места занимает журнал" },
            new SshSnippet { Name = "История загрузок", Group = "Журналы", Command = "journalctl --no-pager --list-boots | head -5", Description = "Список сохранённых загрузок с датами" },
            new SshSnippet { Name = "Всё по sshd", Group = "Журналы", Command = "journalctl _COMM=sshd --no-pager -n 20", Description = "События SSH-демона" },
            new SshSnippet { Name = "Всё по cron", Group = "Журналы", Command = "journalctl _COMM=cron --no-pager -n 15 2>/dev/null; journalctl _COMM=crond --no-pager -n 15 2>/dev/null", Description = "События планировщика cron" },
            new SshSnippet { Name = "Кто делал sudo", Group = "Журналы", Command = "journalctl _COMM=sudo --no-pager -n 15", Description = "Кто и когда повышал права" },
            new SshSnippet { Name = "syslog хвост", Group = "Журналы", Command = "tail -n 30 /var/log/syslog 2>/dev/null || tail -n 30 /var/log/messages 2>/dev/null", Description = "Хвост общесистемного лога" },
            new SshSnippet { Name = "auth хвост", Group = "Журналы", Command = "tail -n 20 /var/log/auth.log 2>/dev/null || tail -n 20 /var/log/secure 2>/dev/null", Description = "Хвост лога аутентификации" },
            new SshSnippet { Name = "kern хвост", Group = "Журналы", Command = "tail -n 20 /var/log/kern.log 2>/dev/null || dmesg | tail -20", Description = "Хвост ядерного лога" },
            new SshSnippet { Name = "Ставилось deb", Group = "Журналы", Command = "tail -n 20 /var/log/dpkg.log 2>/dev/null || echo \"не debian\"", Description = "Последние установки пакетов" },
            new SshSnippet { Name = "Ставилось rpm", Group = "Журналы", Command = "tail -n 20 /var/log/yum.log 2>/dev/null || echo \"не rhel\"", Description = "Установки через yum" },
            new SshSnippet { Name = "faillog", Group = "Журналы", Command = "faillog -a 2>/dev/null | head -10 || echo \"faillog пуст\"", Description = "Сводка неудачных входов" },
            new SshSnippet { Name = "Входы с датами", Group = "Журналы", Command = "last -n 5 -F | head -10", Description = "Пять входов с полными датами" },
            new SshSnippet { Name = "btmp", Group = "Журналы", Command = "lastb -n 10 2>/dev/null | head -12 || echo \"btmp пуст\"", Description = "Неудачные входы из btmp" },
            new SshSnippet { Name = "Ошибки dmesg", Group = "Журналы", Command = "dmesg -l err 2>/dev/null | tail -10 || dmesg | grep -iE \"error|fail\" | tail -10", Description = "Ошибки уровня ядра" },
            new SshSnippet { Name = "Варнинги dmesg", Group = "Журналы", Command = "dmesg -l warn 2>/dev/null | tail -10 || echo \"-\"", Description = "Предупреждения ядра" },
            new SshSnippet { Name = "SELinux отказы", Group = "Журналы", Command = "ausearch -m avc -ts today 2>/dev/null | head -10 || echo \"auditd нет\"", Description = "Отказы SELinux за сегодня" },
            new SshSnippet { Name = "Ошибки nginx", Group = "Журналы", Command = "tail -n 15 /var/log/nginx/error.log 2>/dev/null || echo \"логов nginx нет\"", Description = "Ошибки веб-сервера nginx" },
            new SshSnippet { Name = "Ошибки apache", Group = "Журналы", Command = "tail -n 15 /var/log/apache2/error.log 2>/dev/null || tail -n 15 /var/log/httpd/error_log 2>/dev/null || echo \"нет\"", Description = "Ошибки веб-сервера apache" },
            new SshSnippet { Name = "Ошибки MySQL", Group = "Журналы", Command = "tail -n 15 /var/log/mysql/error.log 2>/dev/null || echo \"нет\"", Description = "Ошибки сервера баз данных" },
            new SshSnippet { Name = "Почтовый лог", Group = "Журналы", Command = "tail -n 15 /var/log/mail.log 2>/dev/null || echo \"нет\"", Description = "Почтовые события системы" },
            new SshSnippet { Name = "Настройки ротации", Group = "Журналы", Command = "cat /etc/logrotate.conf | grep -v \"^#\" | grep -v \"^$\" | head -15", Description = "Конфиг ротации логов без комментариев" },
            new SshSnippet { Name = "Вес логов", Group = "Журналы", Command = "du -sh /var/log", Description = "Размер каталога логов целиком" },
            new SshSnippet { Name = "Архивные логи", Group = "Журналы", Command = "ls -lh /var/log/*.gz 2>/dev/null | head -10 || echo \"архивов нет\"", Description = "Сжатые ротированные логи" },
            new SshSnippet { Name = "Хвост auditd", Group = "Журналы", Command = "tail -n 10 /var/log/audit/audit.log 2>/dev/null || echo \"auditd нет\"", Description = "События системного аудита" },
            new SshSnippet { Name = "Тип файла пример", Group = "Файлы", Command = "file /etc/hosts /bin/sh", Description = "Что за файлы: текст, скрипт или бинарь" },
            new SshSnippet { Name = "Суммы примера", Group = "Файлы", Command = "md5sum /etc/hosts | head -2; sha256sum /etc/hosts | head -2", Description = "md5 и sha256 контрольные суммы" },
            new SshSnippet { Name = "Пустые в /etc", Group = "Файлы", Command = "find /etc -maxdepth 1 -type f -empty 2>/dev/null", Description = "Файлы нулевого размера в конфигах" },
            new SshSnippet { Name = "Скрытые дома", Group = "Файлы", Command = "ls -la ~ | grep \"^\\.\" | head -20", Description = "Точечные файлы домашнего каталога" },
            new SshSnippet { Name = "Счёт бинарей", Group = "Файлы", Command = "find /usr/bin -maxdepth 1 -type f -executable 2>/dev/null | wc -l", Description = "Сколько исполняемых файлов в /usr/bin" },
            new SshSnippet { Name = "SUID-список", Group = "Файлы", Command = "find /usr/bin /bin -maxdepth 1 -perm -4000 -type f 2>/dev/null", Description = "Бинари с SUID-битом (повышение прав)" },
            new SshSnippet { Name = "SGID-список", Group = "Файлы", Command = "find /usr/bin -maxdepth 1 -perm -2000 -type f 2>/dev/null", Description = "Бинари с SGID-битом" },
            new SshSnippet { Name = "Пишут все", Group = "Файлы", Command = "find /etc -maxdepth 2 -type f -perm -0002 2>/dev/null | head -10", Description = "Мировые на запись в конфигах - это плохо" },
            new SshSnippet { Name = "Без владельца", Group = "Файлы", Command = "find / -maxdepth 4 -nouser -type f 2>/dev/null | head -10 || echo \"таких нет\"", Description = "Ничейные файлы без владельца" },
            new SshSnippet { Name = "Старьё var/tmp", Group = "Файлы", Command = "find /var/tmp -type f -atime +30 2>/dev/null | head -10", Description = "Нетронутые больше 30 дней" },
            new SshSnippet { Name = "Новое в /tmp", Group = "Файлы", Command = "find /tmp -type f -mmin -60 2>/dev/null | head -10", Description = "Созданные за последний час" },
            new SshSnippet { Name = "Вес домашек", Group = "Файлы", Command = "du -sh /home/* /root 2>/dev/null | sort -h", Description = "Домашние каталоги по весу" },
            new SshSnippet { Name = "Вес /usr", Group = "Файлы", Command = "du -sh /usr", Description = "Размер каталога /usr целиком" },
            new SshSnippet { Name = "Вес /opt", Group = "Файлы", Command = "du -sh /opt 2>/dev/null || echo \"opt нет\"", Description = "Размер каталога /opt" },
            new SshSnippet { Name = "Вес /srv", Group = "Файлы", Command = "du -sh /srv 2>/dev/null || echo \"srv нет\"", Description = "Размер каталога /srv" },
            new SshSnippet { Name = "Файлов в /etc", Group = "Файлы", Command = "find /etc -type f 2>/dev/null | wc -l", Description = "Счётчик файлов конфигов" },
            new SshSnippet { Name = "Каталогов в /etc", Group = "Файлы", Command = "find /etc -type d 2>/dev/null | wc -l", Description = "Счётчик каталогов конфигов" },
            new SshSnippet { Name = "Битые симлинки", Group = "Файлы", Command = "find /usr/bin -maxdepth 1 -xtype l 2>/dev/null | head -10 || echo \"битых нет\"", Description = "Висячие ссылки в никуда" },
            new SshSnippet { Name = "Жёсткие ссылки", Group = "Файлы", Command = "find /etc -maxdepth 1 -type f -links +1 2>/dev/null | head -5 || echo \"нет\"", Description = "Файлы с несколькими жёсткими ссылками" },
            new SshSnippet { Name = "stat подробно", Group = "Файлы", Command = "stat /etc/hosts", Description = "Все поля stat: инод, права, времена" },
            new SshSnippet { Name = "Права октально", Group = "Файлы", Command = "stat -c %a /etc/hosts /etc/passwd", Description = "Права цифрами вроде 644" },
            new SshSnippet { Name = "Владелец пример", Group = "Файлы", Command = "stat -c %U:%G /etc/hosts", Description = "Чей файл: юзер и группа" },
            new SshSnippet { Name = "Когда меняли", Group = "Файлы", Command = "stat -c %y /etc/hosts | cut -d. -f1", Description = "Время изменения без наносекунд" },
            new SshSnippet { Name = "Строк счёт", Group = "Файлы", Command = "wc -l /etc/hosts /etc/passwd", Description = "Число строк в файлах" },
            new SshSnippet { Name = "Байт счёт", Group = "Файлы", Command = "wc -c /etc/hosts", Description = "Размер файла в байтах" },
            new SshSnippet { Name = "Длиннейшая", Group = "Файлы", Command = "wc -L /etc/passwd", Description = "Длина самой длинной строки" },
            new SshSnippet { Name = "Сортировка пример", Group = "Файлы", Command = "sort /etc/hosts | head -10", Description = "Отсортированные строки" },
            new SshSnippet { Name = "Шеллы уникально", Group = "Файлы", Command = "cut -d: -f7 /etc/passwd | sort -u", Description = "Шеллы без повторов" },
            new SshSnippet { Name = "diff пример", Group = "Файлы", Command = "diff /etc/hosts /etc/hosts.allow 2>/dev/null | head -10 || echo \"allow нет\"", Description = "Разница двух файлов" },
            new SshSnippet { Name = "localhost где", Group = "Файлы", Command = "grep -r \"localhost\" /etc/hosts /etc/hostname 2>/dev/null", Description = "В каких файлах встречается" },
            new SshSnippet { Name = "Куда localtime", Group = "Файлы", Command = "realpath /etc/localtime 2>/dev/null || readlink -f /etc/localtime", Description = "Цель ссылки часового пояса" },
            new SshSnippet { Name = "localtime ссылка?", Group = "Файлы", Command = "test -L /etc/localtime && echo \"симлинк\" || echo \"файл\"", Description = "Ссылка это или обычный файл" },
            new SshSnippet { Name = "Проверка +x", Group = "Файлы", Command = "test -x /bin/ls && echo \"ls исполняемый\"", Description = "Исполняемый ли файл" },
            new SshSnippet { Name = "shadow закрыт?", Group = "Файлы", Command = "test -r /etc/shadow && echo \"shadow читается?!\" || echo \"shadow закрыт (норма)\"", Description = "Доступен ли shadow на чтение" },
            new SshSnippet { Name = "/etc каталог?", Group = "Файлы", Command = "test -d /etc && echo \"/etc — каталог\"", Description = "Проверка типа пути" },
            new SshSnippet { Name = "Первые group", Group = "Файлы", Command = "head -n 5 /etc/group", Description = "Первые 5 строк group" },
            new SshSnippet { Name = "UID/GID числа", Group = "Права", Command = "id -u; id -g", Description = "Числовые идентификаторы пользователя и группы" },
            new SshSnippet { Name = "umask цифры", Group = "Права", Command = "umask", Description = "Маска создания файлов цифрами" },
            new SshSnippet { Name = "umask буквы", Group = "Права", Command = "umask -S", Description = "Та же маска символами u=rwx" },
            new SshSnippet { Name = "Права дома", Group = "Права", Command = "stat -c %a ~", Description = "Права домашнего каталога цифрами" },
            new SshSnippet { Name = "Права .ssh", Group = "Права", Command = "stat -c %a ~/.ssh 2>/dev/null || echo \"нет .ssh\"", Description = "Права каталога ключей (должно быть 700)" },
            new SshSnippet { Name = "Права ключей", Group = "Права", Command = "ls -l ~/.ssh/id_* 2>/dev/null | awk '{print $1, $9}' || echo \"ключей нет\"", Description = "Права key-файлов (приватным нужно 600)" },
            new SshSnippet { Name = "Права authorized", Group = "Права", Command = "stat -c %a ~/.ssh/authorized_keys 2>/dev/null || echo \"нет файла\"", Description = "Права файла доверенных ключей" },
            new SshSnippet { Name = "Чей дом", Group = "Права", Command = "stat -c %U ~", Description = "Владелец домашнего каталога" },
            new SshSnippet { Name = "ACL дома", Group = "Права", Command = "getfacl ~ 2>/dev/null | head -10 || echo \"acl нет\"", Description = "Расширенные списки доступа домашки" },
            new SshSnippet { Name = "Атрибуты hosts", Group = "Права", Command = "lsattr /etc/hosts 2>/dev/null || echo \"нет lsattr\"", Description = "Флаги файла вроде immutable" },
            new SshSnippet { Name = "Immutable в /etc", Group = "Права", Command = "lsattr -R /etc 2>/dev/null | grep -E \"^....i\" | head -10 || echo \"таких нет\"", Description = "Файлы, запрещённые к изменению" },
            new SshSnippet { Name = "Права /tmp", Group = "Права", Command = "ls -ld /tmp", Description = "Права и sticky-бит общей временной" },
            new SshSnippet { Name = "Sticky-каталоги", Group = "Права", Command = "find / -maxdepth 3 -type d -perm -1000 2>/dev/null | head -10", Description = "Каталоги со sticky-битом" },
            new SshSnippet { Name = "Виден ли shadow", Group = "Права", Command = "ls -l /etc/shadow 2>/dev/null || echo \"не видно\"", Description = "Права файла теневых паролей" },
            new SshSnippet { Name = "Capabilities", Group = "Права", Command = "getcap -r /usr/bin 2>/dev/null | head -10 || echo \"cap нет\"", Description = "Особые привилегии бинарей" },
            new SshSnippet { Name = "Доки пакетов", Group = "Архивы", Command = "ls /usr/share/doc | head -20", Description = "Документация установленных пакетов" },
            new SshSnippet { Name = "Changelog bash", Group = "Архивы", Command = "zcat /usr/share/doc/bash/changelog*.gz 2>/dev/null | head -10 || echo \"нет\"", Description = "История изменений пакета bash" },
            new SshSnippet { Name = "Сжатая дока", Group = "Архивы", Command = "ls /usr/share/doc/*/*.gz 2>/dev/null | head -10", Description = "Сжатая документация пакетов" },
            new SshSnippet { Name = "Man для ls", Group = "Архивы", Command = "man -w ls 2>/dev/null || echo \"man нет\"", Description = "Где лежит мануал команды" },
            new SshSnippet { Name = "Info есть?", Group = "Архивы", Command = "info --version 2>/dev/null | head -1 || echo \"info нет\"", Description = "Есть ли система info-доков" },
            new SshSnippet { Name = "Конфиг ядра из /proc", Group = "Архивы", Command = "zcat /proc/config.gz 2>/dev/null | head -5 || echo \"config.gz нет\"", Description = "Конфиг запущенного ядра" },
            new SshSnippet { Name = "Целостность gz", Group = "Архивы", Command = "gzip -t /var/log/*.gz 2>/dev/null && echo \"gz целые\" || echo \"gz нет/битые\"", Description = "Проверка gzip-архивов на целостность" },
            new SshSnippet { Name = "Целостность bz2", Group = "Архивы", Command = "bzip2 -t /var/log/*.bz2 2>/dev/null && echo \"bz2 целые\" || echo \"bz2 нет\"", Description = "Проверка bzip2-архивов" },
            new SshSnippet { Name = "Поиск zip", Group = "Архивы", Command = "find /usr/share -maxdepth 3 -name \"*.zip\" 2>/dev/null | head -5 || echo \"zip нет\"", Description = "Где лежат zip-архивы" },
            new SshSnippet { Name = "Шапки zip", Group = "Архивы", Command = "find /usr/share -maxdepth 4 -name \"*.zip\" -exec zipinfo -h {} \\; 2>/dev/null | head -10 || echo \"zip нет\"", Description = "Краткая информация о найденных zip" },
            new SshSnippet { Name = "Версия tar", Group = "Архивы", Command = "tar --version | head -1", Description = "Какой tar: GNU или bsdtar" },
            new SshSnippet { Name = "Версия unzip", Group = "Архивы", Command = "unzip -v 2>/dev/null | head -3 || echo \"unzip нет\"", Description = "Версия распаковщика zip" },
            new SshSnippet { Name = "Есть ли 7z", Group = "Архивы", Command = "7z i 2>/dev/null | head -5 || echo \"7z нет\"", Description = "Проверка архиватора 7-Zip" },
            new SshSnippet { Name = "Версия gzip", Group = "Архивы", Command = "gzip --version | head -1", Description = "Версия компрессора gzip" },
            new SshSnippet { Name = "Версия xz", Group = "Архивы", Command = "xz --version | head -1", Description = "Версия компрессора xz" },
            new SshSnippet { Name = "Сколько root", Group = "Текст", Command = "grep -c root /etc/passwd", Description = "Число строк со словом root" },
            new SshSnippet { Name = "hosts начисто", Group = "Текст", Command = "grep -v \"^#\" /etc/hosts | grep -v \"^$\"", Description = "Строки hosts без комментариев и пустых" },
            new SshSnippet { Name = "Номера localhost", Group = "Текст", Command = "grep -n localhost /etc/hosts", Description = "Номера строк с совпадениями" },
            new SshSnippet { Name = "IP из hosts", Group = "Текст", Command = "grep -o \"[0-9]*\\.[0-9]*\\.[0-9]*\\.[0-9]*\" /etc/hosts | head -5", Description = "Вытащить только IP-адреса" },
            new SshSnippet { Name = "Живые из passwd", Group = "Текст", Command = "grep -v \"^#\" /etc/passwd | grep -v nologin | grep -v false | head -10", Description = "Учётки с настоящим шеллом" },
            new SshSnippet { Name = "Без регистра", Group = "Текст", Command = "grep -i localhost /etc/hosts | head -5", Description = "Поиск с игнором регистра букв" },
            new SshSnippet { Name = "Целое слово", Group = "Текст", Command = "grep -w \"localhost\" /etc/hosts | head -5", Description = "Только точное слово целиком" },
            new SshSnippet { Name = "Контекст совпадения", Group = "Текст", Command = "grep -C2 -m1 \"localhost\" /etc/hosts", Description = "По две строки вокруг совпадения" },
            new SshSnippet { Name = "Счёт по файлам", Group = "Текст", Command = "grep -rc \"localhost\" /etc/hosts /etc/hostname 2>/dev/null", Description = "Сколько совпадений в каждом файле" },
            new SshSnippet { Name = "Где встречается", Group = "Текст", Command = "grep -rl \"localhost\" /etc/*.conf /etc/hosts 2>/dev/null | head -5", Description = "Список файлов со словом" },
            new SshSnippet { Name = "Голова group", Group = "Текст", Command = "head -n 5 /etc/group", Description = "Первые пять строк group" },
            new SshSnippet { Name = "Хвост group", Group = "Текст", Command = "tail -n 5 /etc/group", Description = "Последние пять строк group" },
            new SshSnippet { Name = "Пропустить 9", Group = "Текст", Command = "tail -n +10 /etc/passwd | head -5", Description = "Вывод начиная с 10-й строки" },
            new SshSnippet { Name = "Чётные строки", Group = "Текст", Command = "sed -n '2~2p' /etc/hosts | head -8", Description = "Каждая вторая строка файла" },
            new SshSnippet { Name = "Строки 2-4", Group = "Текст", Command = "sed -n '2,4p' /etc/hosts", Description = "Диапазон строк по номерам" },
            new SshSnippet { Name = "Без пустых", Group = "Текст", Command = "sed '/^$/d' /etc/hosts | head -10", Description = "Убрать все пустые строки" },
            new SshSnippet { Name = "С номерами", Group = "Текст", Command = "cat -n /etc/hosts | head -8", Description = "Пронумеровать строки" },
            new SshSnippet { Name = "Невидимые символы", Group = "Текст", Command = "cat -A /etc/hosts | head -5", Description = "Табы и концы строк наглядно" },
            new SshSnippet { Name = "Концы строк", Group = "Текст", Command = "cat -E /etc/hosts | head -5", Description = "Маркер конца каждой строки" },
            new SshSnippet { Name = "Юзер и шелл", Group = "Текст", Command = "awk -F: '{print $1\": \"$7}' /etc/passwd | head -10", Description = "Два поля через awk" },
            new SshSnippet { Name = "UID списком", Group = "Текст", Command = "awk -F: '$3 >= 1000 {print $1}' /etc/passwd | tr '\\n' ' '", Description = "Юзеры с UID от 1000 одной строкой" },
            new SshSnippet { Name = "Длинные логины", Group = "Текст", Command = "awk -F: '{print length($1), $1}' /etc/passwd | sort -rn | head -5", Description = "Топ самых длинных имён" },
            new SshSnippet { Name = "Два поля сразу", Group = "Текст", Command = "cut -d: -f1,7 /etc/passwd | head -8", Description = "Имя и шелл через cut" },
            new SshSnippet { Name = "Первые символы", Group = "Текст", Command = "cut -c1-8 /etc/passwd | head -8", Description = "По восемь символов с начала" },
            new SshSnippet { Name = "Шеллы со счётом", Group = "Текст", Command = "cut -d: -f7 /etc/passwd | sort | uniq -c", Description = "Группировка шеллов со счётчиком" },
            new SshSnippet { Name = "Наоборот", Group = "Текст", Command = "sort -r /etc/hosts | head -8", Description = "Сортировка в обратном порядке" },
            new SshSnippet { Name = "Строки по длине", Group = "Текст", Command = "awk '{print length, $0}' /etc/hosts | sort -rn | head -5", Description = "Самые длинные строки первыми" },
            new SshSnippet { Name = "Повторы шеллов", Group = "Текст", Command = "cut -d: -f7 /etc/passwd | sort | uniq -d", Description = "Дублирующиеся значения" },
            new SshSnippet { Name = "Слов счёт", Group = "Текст", Command = "wc -w /etc/hosts /etc/hostname", Description = "Число слов в файлах" },
            new SshSnippet { Name = "Убрать цифры", Group = "Текст", Command = "echo \"a1b2c3\" | tr -d '0-9'", Description = "Фильтр символов на примере" },
            new SshSnippet { Name = "Хвост deb", Group = "Пакеты", Command = "dpkg -l 2>/dev/null | tail -5 || echo \"не debian\"", Description = "Конец списка установленных deb" },
            new SshSnippet { Name = "Число deb", Group = "Пакеты", Command = "dpkg -l 2>/dev/null | grep -c \"^ii\" || echo 0", Description = "Сколько пакетов установлено" },
            new SshSnippet { Name = "Карточка bash", Group = "Пакеты", Command = "dpkg -s bash 2>/dev/null | grep -E \"^(Package|Version|Status)\"", Description = "Версия и статус пакета bash" },
            new SshSnippet { Name = "Файлы bash", Group = "Пакеты", Command = "dpkg -L bash 2>/dev/null | head -10 || echo \"-\"", Description = "Какие файлы ставит пакет bash" },
            new SshSnippet { Name = "Владелец ls", Group = "Пакеты", Command = "dpkg -S /bin/ls 2>/dev/null || echo \"-\"", Description = "Какой пакет владеет файлом ls" },
            new SshSnippet { Name = "SSH-пакеты", Group = "Пакеты", Command = "dpkg -l 2>/dev/null | grep -i ssh | head -10 || echo \"-\"", Description = "Что из SSH установлено" },
            new SshSnippet { Name = "Ядра deb", Group = "Пакеты", Command = "dpkg -l 2>/dev/null | grep -i linux-image | head -10 || echo \"-\"", Description = "Установленные образы ядра" },
            new SshSnippet { Name = "apt список", Group = "Пакеты", Command = "apt list --installed 2>/dev/null | head -5 || echo \"apt нет\"", Description = "Пример вывода apt" },
            new SshSnippet { Name = "Откуда bash", Group = "Пакеты", Command = "apt-cache policy bash 2>/dev/null | head -8 || echo \"apt нет\"", Description = "Из какого репозитория пакет" },
            new SshSnippet { Name = "Зависимости bash", Group = "Пакеты", Command = "apt-cache depends bash 2>/dev/null | head -10 || echo \"apt нет\"", Description = "Что тянет за собой bash" },
            new SshSnippet { Name = "Обратные зависимости", Group = "Пакеты", Command = "apt-cache rdepends bash 2>/dev/null | head -8 || echo \"apt нет\"", Description = "Какие пакеты зависят от bash" },
            new SshSnippet { Name = "RPM список", Group = "Пакеты", Command = "rpm -qa 2>/dev/null | head -5 || echo \"rpm нет\"", Description = "Пример списка rpm" },
            new SshSnippet { Name = "Число rpm", Group = "Пакеты", Command = "rpm -qa 2>/dev/null | wc -l || echo 0", Description = "Сколько rpm-пакетов" },
            new SshSnippet { Name = "Карточка rpm", Group = "Пакеты", Command = "rpm -qi bash 2>/dev/null | head -8 || echo \"-\"", Description = "Информация rpm-пакета" },
            new SshSnippet { Name = "Snap-список", Group = "Пакеты", Command = "snap list 2>/dev/null || echo \"snap нет\"", Description = "Установленные snap-пакеты" },
            new SshSnippet { Name = "Flatpak-список", Group = "Пакеты", Command = "flatpak list 2>/dev/null || echo \"flatpak нет\"", Description = "Установленные flatpak" },
            new SshSnippet { Name = "Python-пакеты", Group = "Пакеты", Command = "pip3 list 2>/dev/null | head -10 || echo \"pip нет\"", Description = "Первые 10 pip-пакетов" },
            new SshSnippet { Name = "Node-пакеты", Group = "Пакеты", Command = "npm -g ls --depth=0 2>/dev/null | head -10 || echo \"npm нет\"", Description = "Глобальные пакеты Node" },
            new SshSnippet { Name = "Ruby-пакеты", Group = "Пакеты", Command = "gem list 2>/dev/null | head -10 || echo \"gem нет\"", Description = "Установленные гемы" },
            new SshSnippet { Name = "Hold-пакеты", Group = "Пакеты", Command = "dpkg --get-selections 2>/dev/null | grep hold | head -5 || echo \"hold нет\"", Description = "Зафиксированные от обновлений" },
            new SshSnippet { Name = "CPU подробно", Group = "Оборудование", Command = "lscpu | head -20", Description = "Процессор детально: модель, ядра, потоки" },
            new SshSnippet { Name = "Ядра списком", Group = "Оборудование", Command = "lscpu -e 2>/dev/null | head -10 || echo \"-\"", Description = "Топология ядер и потоков" },
            new SshSnippet { Name = "Кэши CPU", Group = "Оборудование", Command = "lscpu | grep -i cache", Description = "Кэши L1/L2/L3 процессора" },
            new SshSnippet { Name = "Флаги виртуализации", Group = "Оборудование", Command = "grep -m1 flags /proc/cpuinfo | tr ' ' '\\n' | grep -E \"^(vmx|svm|aes|avx)\" | head -5 || echo \"флагов нет\"", Description = "Поддержка vmx/svm/aes/avx" },
            new SshSnippet { Name = "PCI-устройства", Group = "Оборудование", Command = "lspci 2>/dev/null | head -15 || echo \"lspci нет\"", Description = "Устройства на шинах PCI" },
            new SshSnippet { Name = "Сетевые карты", Group = "Оборудование", Command = "lspci 2>/dev/null | grep -i net | head -5 || echo \"-\"", Description = "Сетевые адаптеры списком" },
            new SshSnippet { Name = "USB", Group = "Оборудование", Command = "lsusb 2>/dev/null || echo \"lsusb нет\"", Description = "Подключённые USB-устройства" },
            new SshSnippet { Name = "Планки памяти", Group = "Оборудование", Command = "dmidecode -t memory 2>/dev/null | grep -E \"Size|Speed|Locator\" | head -12 || echo \"нужен root\"", Description = "DIMM-слоты: объём и скорость" },
            new SshSnippet { Name = "Версия BIOS", Group = "Оборудование", Command = "dmidecode -s bios-version 2>/dev/null || echo \"нужен root\"", Description = "Версия прошивки BIOS/UEFI" },
            new SshSnippet { Name = "Серийник", Group = "Оборудование", Command = "dmidecode -s system-serial-number 2>/dev/null || echo \"нужен root\"", Description = "Серийный номер сервера" },
            new SshSnippet { Name = "SCSI-диски", Group = "Оборудование", Command = "lsscsi 2>/dev/null || echo \"lsscsi нет\"", Description = "SCSI/SATA устройства" },
            new SshSnippet { Name = "NVMe", Group = "Оборудование", Command = "ls /dev/nvme* 2>/dev/null || echo \"nvme нет\"", Description = "NVMe-накопители" },
            new SshSnippet { Name = "Диски с ФС", Group = "Оборудование", Command = "lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT", Description = "Таблица дисков с файловыми системами" },
            new SshSnippet { Name = "Приводы", Group = "Оборудование", Command = "ls /dev/sr* /dev/cdrom 2>/dev/null || echo \"приводов нет\"", Description = "CD/DVD и оптические приводы" },
            new SshSnippet { Name = "Видеокарта", Group = "Оборудование", Command = "lspci 2>/dev/null | grep -i vga | head -3 || echo \"-\"", Description = "Графический адаптер" },
            new SshSnippet { Name = "Температуры", Group = "Оборудование", Command = "sensors 2>/dev/null | head -15 || echo \"sensors нет\"", Description = "Датчики нагрева компонентов" },
            new SshSnippet { Name = "Модель сервера", Group = "Оборудование", Command = "dmidecode -s system-product-name 2>/dev/null || cat /sys/class/dmi/id/product_name 2>/dev/null || echo \"-\"", Description = "Что за железо по DMI" },
            new SshSnippet { Name = "Тип корпуса", Group = "Оборудование", Command = "cat /sys/class/dmi/id/chassis_type 2>/dev/null || echo \"-\"", Description = "Числовой код типа шасси по DMI" },
            new SshSnippet { Name = "Вендор", Group = "Оборудование", Command = "cat /sys/class/dmi/id/sys_vendor 2>/dev/null || echo \"-\"", Description = "Производитель оборудования" },
            new SshSnippet { Name = "TPM", Group = "Оборудование", Command = "ls /dev/tpm* 2>/dev/null || echo \"tpm нет\"", Description = "Модуль доверенной загрузки" },
            new SshSnippet { Name = "Модули списком", Group = "Ядро и модули", Command = "lsmod | head -20", Description = "Загруженные модули ядра с размерами" },
            new SshSnippet { Name = "Счёт модулей", Group = "Ядро и модули", Command = "lsmod | tail -n +2 | wc -l", Description = "Сколько модулей загружено" },
            new SshSnippet { Name = "Модуль ext4", Group = "Ядро и модули", Command = "modinfo ext4 2>/dev/null | head -8 || echo \"-\"", Description = "Информация о модуле на примере ext4" },
            new SshSnippet { Name = "sysctl первые", Group = "Ядро и модули", Command = "sysctl -a 2>/dev/null | head -20", Description = "Первые 20 параметров ядра" },
            new SshSnippet { Name = "Имя через sysctl", Group = "Ядро и модули", Command = "sysctl kernel.hostname", Description = "Имя хоста глазами ядра" },
            new SshSnippet { Name = "Лимит потоков", Group = "Ядро и модули", Command = "sysctl kernel.threads-max", Description = "Максимальное число потоков" },
            new SshSnippet { Name = "PID максимум", Group = "Ядро и модули", Command = "cat /proc/sys/kernel/pid_max", Description = "Потолок номеров PID" },
            new SshSnippet { Name = "Семафоры", Group = "Ядро и модули", Command = "cat /proc/sys/kernel/sem", Description = "Лимиты IPC-семафоров" },
            new SshSnippet { Name = "SHM-сегмент", Group = "Ядро и модули", Command = "cat /proc/sys/kernel/shmmax", Description = "Максимальный размер SHM-сегмента" },
            new SshSnippet { Name = "SHM-страницы", Group = "Ядро и модули", Command = "cat /proc/sys/kernel/shmall", Description = "Лимит страниц разделяемой памяти" },
            new SshSnippet { Name = "Сообщения", Group = "Ядро и модули", Command = "cat /proc/sys/kernel/msgmax 2>/dev/null || echo \"-\"", Description = "Лимит размера msgqueue-сообщения" },
            new SshSnippet { Name = "Автозагрузка", Group = "Ядро и модули", Command = "ls /etc/modules-load.d/ 2>/dev/null || echo \"нет\"", Description = "Модули, грузямые при старте" },
            new SshSnippet { Name = "Blacklist", Group = "Ядро и модули", Command = "cat /etc/modprobe.d/* 2>/dev/null | grep -i blacklist | head -10 || echo \"нет\"", Description = "Модули, запрещённые к загрузке" },
            new SshSnippet { Name = "Зависимости ext4", Group = "Ядро и модули", Command = "modprobe --show-depends ext4 2>/dev/null | head -8 || echo \"-\"", Description = "Что тянет за собой ext4" },
            new SshSnippet { Name = "Версия kmod", Group = "Ядро и модули", Command = "modprobe --version 2>/dev/null || kmod --version 2>/dev/null || echo \"-\"", Description = "Версия утилит работы с модулями" },
            new SshSnippet { Name = "Тест sudo-доступа", Group = "Безопасность", Command = "sudo -n -v 2>&1; echo \"код: $?\"", Description = "Есть ли sudo без пароля и код возврата" },
            new SshSnippet { Name = "Пароль root", Group = "Безопасность", Command = "sudo -n passwd -S root 2>&1 | head -2 || passwd -S root 2>&1 | head -2", Description = "Статус и срок пароля root" },
            new SshSnippet { Name = "Мой пароль", Group = "Безопасность", Command = "passwd -S 2>&1 | head -2", Description = "Статус собственного пароля" },
            new SshSnippet { Name = "Без пароля", Group = "Безопасность", Command = "getent shadow 2>/dev/null | awk -F: '$2 == \"\" {print $1}' | head -10 || echo \"shadow закрыт (норма)\"", Description = "Учётки с пустым паролем" },
            new SshSnippet { Name = "Ещё UID 0", Group = "Безопасность", Command = "getent passwd | awk -F: '$3 == 0 {print $1}'", Description = "Кто кроме root имеет UID 0" },
            new SshSnippet { Name = "Привилегии групп", Group = "Безопасность", Command = "getent group | grep -E \"sudo|wheel|admin\" | head -5 || echo \"таких нет\"", Description = "Привилегированные группы sudo/wheel" },
            new SshSnippet { Name = "Входы root", Group = "Безопасность", Command = "last -n 3 root 2>/dev/null | head -5 || echo \"-\"", Description = "Последние входы пользователя root" },
            new SshSnippet { Name = "Неудачи root", Group = "Безопасность", Command = "lastb -n 5 root 2>/dev/null | head -7 || echo \"-\"", Description = "Неудачные попытки входа root" },
            new SshSnippet { Name = "Сессии сейчас", Group = "Безопасность", Command = "last -n 10 | grep -i \"still\" | head -10 || last -n 10 | head -12", Description = "Активные сессии входа прямо сейчас" },
            new SshSnippet { Name = "Файлы cron", Group = "Безопасность", Command = "ls -la /etc/cron* 2>/dev/null | head -15", Description = "Файлы планировщика на диске" },
            new SshSnippet { Name = "SUID по системе", Group = "Безопасность", Command = "find / -maxdepth 4 -perm -4000 -type f 2>/dev/null | head -15", Description = "Все SUID-файлы верхних уровней" },
            new SshSnippet { Name = "SGID по системе", Group = "Безопасность", Command = "find / -maxdepth 4 -perm -2000 -type f 2>/dev/null | head -10", Description = "Все SGID-файлы верхних уровней" },
            new SshSnippet { Name = "Ключей пускают", Group = "Безопасность", Command = "wc -l < ~/.ssh/authorized_keys 2>/dev/null || echo 0", Description = "Число ключей в authorized_keys" },
            new SshSnippet { Name = "Отпечаток ключа", Group = "Безопасность", Command = "ssh-keygen -l -f ~/.ssh/id_rsa.pub 2>/dev/null || ssh-keygen -l -f ~/.ssh/id_ed25519.pub 2>/dev/null || echo \"ключей нет\"", Description = "SHA256-отпечаток своего ключа" },
            new SshSnippet { Name = "Начало known_hosts", Group = "Безопасность", Command = "head -3 ~/.ssh/known_hosts 2>/dev/null || echo \"нет\"", Description = "Первые записи известных хостов" },
            new SshSnippet { Name = "Ключи в агенте", Group = "Безопасность", Command = "ssh-add -l 2>/dev/null || echo \"агента нет\"", Description = "Что загружено в ssh-agent" },
            new SshSnippet { Name = "Опасные алиасы", Group = "Безопасность", Command = "alias | grep -iE \"rm|dd|mkfs|shutdown\" || echo \"опасных нет\"", Description = "Проверка алиасов на опасные команды" },
            new SshSnippet { Name = "Уязвимости CPU", Group = "Безопасность", Command = "cat /sys/devices/system/cpu/vulnerabilities/* 2>/dev/null | head -10", Description = "Mitigations процессора (Meltdown и др.)" },
            new SshSnippet { Name = "ASLR вкл?", Group = "Безопасность", Command = "cat /proc/sys/kernel/randomize_va_space", Description = "Включена ли рандомизация памяти" },
            new SshSnippet { Name = "Куда core", Group = "Безопасность", Command = "cat /proc/sys/kernel/core_pattern", Description = "Шаблон core-дампов при падениях" },
            new SshSnippet { Name = "Время UTC", Group = "Дата и время", Command = "date -u", Description = "Текущее время по Гринвичу" },
            new SshSnippet { Name = "Unix timestamp", Group = "Дата и время", Command = "date +%s", Description = "Секунд с 1 января 1970" },
            new SshSnippet { Name = "Формат ISO", Group = "Дата и время", Command = "date -Iseconds", Description = "Дата в формате ISO-8601 с зоной" },
            new SshSnippet { Name = "Календарь", Group = "Дата и время", Command = "cal 2>/dev/null || ncal 2>/dev/null || echo \"cal нет\"", Description = "Календарь текущего месяца" },
            new SshSnippet { Name = "День недели", Group = "Дата и время", Command = "date +%A", Description = "Какой сегодня день недели" },
            new SshSnippet { Name = "Название зоны", Group = "Дата и время", Command = "timedatectl 2>/dev/null | grep -i \"time zone\" || cat /etc/timezone 2>/dev/null || echo \"-\"", Description = "Имя часового пояса системы" },
            new SshSnippet { Name = "NTP синхрон", Group = "Дата и время", Command = "timedatectl 2>/dev/null | grep -i ntp || echo \"-\"", Description = "Синхронизированы ли часы по NTP" },
            new SshSnippet { Name = "Смещение часов", Group = "Дата и время", Command = "chronyc tracking 2>/dev/null | grep -i offset || ntpq -p 2>/dev/null | head -5 || echo \"хроники нет\"", Description = "Дрейф системных часов" },
            new SshSnippet { Name = "Мини-сводка", Group = "Диагностика", Command = "echo \"=== $(hostname) $(date +%H:%M) ===\"; uptime; free -h | tail -2; df -h / /var 2>/dev/null | tail -3", Description = "Хост одной картинкой: время, память и диски" },
            new SshSnippet { Name = "Load числом", Group = "Диагностика", Command = "cat /proc/loadavg | awk '{print $1}'", Description = "Первая цифра load average" },
            new SshSnippet { Name = "Память в %", Group = "Диагностика", Command = "free | awk '/Mem:/ {printf \"%.0f%%\\n\", $3/$2*100}'", Description = "Процент занятой оперативной памяти" },
            new SshSnippet { Name = "Корень в %", Group = "Диагностика", Command = "df / | tail -1 | awk '{print $5}'", Description = "Процент занятости корневого раздела" },
            new SshSnippet { Name = "SSH-порт жив?", Group = "Диагностика", Command = "(exec 3<>/dev/tcp/127.0.0.1/22) 2>/dev/null && echo \"22 открыт\" || echo \"22 закрыт\"", Description = "Проверка локального SSH-порта без telnet" },
            new SshSnippet { Name = "DNS да/нет", Group = "Диагностика", Command = "getent hosts ya.ru >/dev/null 2>&1 && echo \"DNS ok\" || echo \"DNS мёртв\"", Description = "Работает ли разрешение имён" },
            new SshSnippet { Name = "Шлюз да/нет", Group = "Диагностика", Command = "gw=$(ip route show default 2>/dev/null | awk '{print $3}'); ping -c1 -W1 $gw >/dev/null 2>&1 && echo \"шлюз ok\" || echo \"шлюз мёртв\"", Description = "Отвечает ли шлюз по умолчанию" },
            new SshSnippet { Name = "Инет да/нет", Group = "Диагностика", Command = "ping -c1 -W2 8.8.8.8 >/dev/null 2>&1 && echo \"инет ok\" || echo \"инета нет\"", Description = "Есть ли выход наружу одним пакетом" },
            new SshSnippet { Name = "Запись 50МБ", Group = "Диагностика", Command = "(time dd if=/dev/zero of=/tmp/wtest bs=1M count=50 conv=fsync 2>&1 | grep -E \"copied|MB/s\"); rm -f /tmp/wtest", Description = "Тест скорости записи с автоочисткой" },
            new SshSnippet { Name = "Чтение диска", Group = "Диагностика", Command = "time dd if=/dev/zero of=/dev/null bs=1M count=200 2>&1 | grep -E \"copied|MB/s\"", Description = "Скорость чтения 200 мегабайт" },
