            new SshSnippet { Name = "IDLE CPU", Group = "Диагностика", Command = "vmstat 1 2 | tail -1 | awk '{print \"idle=\" $15\"%\"}'", Description = "Процент простоя процессора" },
            new SshSnippet { Name = "SYS CPU", Group = "Диагностика", Command = "vmstat 1 2 | tail -1 | awk '{print \"sys=\" $14\"%\"}'", Description = "Процент системного времени CPU" },
            new SshSnippet { Name = "USER CPU", Group = "Диагностика", Command = "vmstat 1 2 | tail -1 | awk '{print \"user=\" $13\"%\"}'", Description = "Процент пользовательского времени" },
            new SshSnippet { Name = "Своп in/out", Group = "Диагностика", Command = "vmstat 1 2 | tail -1 | awk '{print \"si=\" $7\" so=\" $8}'", Description = "Активность подкачки за секунду" },
