            new SshSnippet { Name = "Шифр сайта", Group = "Web и HTTP", Command = "echo | openssl s_client -connect ya.ru:443 2>/dev/null | grep -i cipher | head -3 || echo \"-\"", Description = "Какой шифр negotiated" },
